#!/usr/bin/env python3
"""Generate Aurora's tiny Vulkan shaders without an external shader compiler."""
import argparse
from pathlib import Path
import struct

MAGIC = 0x07230203
VERSION = 0x00010000


def inst(op, *operands):
    return [((1 + len(operands)) << 16) | op, *operands]


def string_words(value):
    data = value.encode("utf-8") + b"\0"
    data += b"\0" * ((4 - len(data) % 4) % 4)
    return list(struct.unpack("<" + "I" * (len(data) // 4), data))


def entry_point(model, function, name, interfaces):
    operands = [model, function, *string_words(name), *interfaces]
    return inst(15, *operands)


def decorate(target, decoration, *args):
    return inst(71, target, decoration, *args)


def module(words, bound):
    return [MAGIC, VERSION, 0, bound, 0, *words]


def vertex_shader():
    w = []
    w += inst(17, 1)  # OpCapability Shader
    w += inst(14, 0, 1)  # Logical, GLSL450
    w += entry_point(0, 17, "main", [11, 12, 13, 14, 15, 16])
    w += decorate(11, 30, 0)  # Location
    w += decorate(12, 30, 1)
    w += decorate(13, 30, 2)
    w += decorate(14, 30, 0)
    w += decorate(15, 30, 1)
    w += decorate(16, 11, 0)  # BuiltIn Position
    w += inst(19, 1)  # void
    w += inst(33, 2, 1)  # function type -> void
    w += inst(22, 3, 32)  # float32
    w += inst(23, 4, 3, 2)  # vec2
    w += inst(23, 5, 3, 4)  # vec4
    w += inst(32, 6, 1, 4)  # ptr Input vec2
    w += inst(32, 7, 1, 5)  # ptr Input vec4
    w += inst(32, 8, 3, 4)  # ptr Output vec2
    w += inst(32, 9, 3, 5)  # ptr Output vec4
    w += inst(59, 6, 11, 1)
    w += inst(59, 6, 12, 1)
    w += inst(59, 7, 13, 1)
    w += inst(59, 8, 14, 3)
    w += inst(59, 9, 15, 3)
    w += inst(59, 9, 16, 3)
    w += inst(43, 3, 22, struct.unpack("<I", struct.pack("<f", 0.0))[0])
    w += inst(43, 3, 23, struct.unpack("<I", struct.pack("<f", 1.0))[0])
    w += inst(54, 1, 17, 0, 2)
    w += inst(248, 18)
    w += inst(61, 4, 19, 11)
    w += inst(61, 4, 20, 12)
    w += inst(61, 5, 21, 13)
    w += inst(80, 5, 24, 19, 22, 23)
    w += inst(62, 16, 24)
    w += inst(62, 14, 20)
    w += inst(62, 15, 21)
    w += inst(253)
    w += inst(56)
    return module(w, 25)


def fragment_shader():
    w = []
    w += inst(17, 1)
    w += inst(14, 0, 1)
    w += entry_point(4, 16, "main", [11, 13, 15])
    w += inst(16, 16, 7)  # OriginUpperLeft
    w += decorate(9, 34, 0)  # DescriptorSet
    w += decorate(9, 33, 0)  # Binding
    w += decorate(11, 30, 0)
    w += decorate(13, 30, 1)
    w += decorate(15, 30, 0)
    w += inst(19, 1)
    w += inst(33, 2, 1)
    w += inst(22, 3, 32)
    w += inst(23, 4, 3, 2)
    w += inst(23, 5, 3, 4)
    w += inst(25, 6, 3, 1, 0, 0, 0, 1, 0)  # image2D sampled float
    w += inst(27, 7, 6)
    w += inst(32, 8, 0, 7)  # UniformConstant
    w += inst(59, 8, 9, 0)
    w += inst(32, 10, 1, 4)
    w += inst(59, 10, 11, 1)
    w += inst(32, 12, 1, 5)
    w += inst(59, 12, 13, 1)
    w += inst(32, 14, 3, 5)
    w += inst(59, 14, 15, 3)
    w += inst(54, 1, 16, 0, 2)
    w += inst(248, 17)
    w += inst(61, 7, 18, 9)
    w += inst(61, 4, 19, 11)
    w += inst(87, 5, 20, 18, 19)
    w += inst(61, 5, 21, 13)
    w += inst(81, 3, 22, 21, 0)
    w += inst(81, 3, 23, 21, 1)
    w += inst(81, 3, 24, 21, 2)
    w += inst(81, 3, 25, 21, 3)
    w += inst(81, 3, 26, 20, 0)
    w += inst(133, 3, 27, 25, 26)
    w += inst(80, 5, 28, 22, 23, 24, 27)
    w += inst(62, 15, 28)
    w += inst(253)
    w += inst(56)
    return module(w, 29)


def write_spv(path, words):
    path.write_bytes(struct.pack("<" + "I" * len(words), *words))


def write_d(path, vertex, fragment):
    def fmt(words):
        lines = []
        for i in range(0, len(words), 8):
            lines.append("    " + ", ".join(f"0x{x:08x}u" for x in words[i:i+8]))
        return ",\n".join(lines)
    path.write_text(
        "module aurora.vulkan.shaders;\n\n"
        "// Generated by tools/make_spirv.py.\n"
        "immutable uint[] vertexShaderSpirv = [\n" + fmt(vertex) + "\n];\n\n"
        "immutable uint[] fragmentShaderSpirv = [\n" + fmt(fragment) + "\n];\n"
    )


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--output-root",
        type=Path,
        default=Path(__file__).resolve().parents[1],
        help="project-shaped directory receiving shaders/ and source/",
    )
    args = parser.parse_args()

    root = args.output_root.resolve()
    (root / "shaders").mkdir(parents=True, exist_ok=True)
    (root / "source" / "aurora" / "vulkan").mkdir(parents=True, exist_ok=True)
    vertex = vertex_shader()
    fragment = fragment_shader()
    write_spv(root / "shaders" / "aurora.vert.spv", vertex)
    write_spv(root / "shaders" / "aurora.frag.spv", fragment)
    write_d(root / "source" / "aurora" / "vulkan" / "shaders.d", vertex, fragment)
    print(f"vertex: {len(vertex)} words; fragment: {len(fragment)} words")


if __name__ == "__main__":
    main()
